const CAP_MATURITY_FA={BASIC:'پایه',GOOD:'خوب',ADVANCED:'پیشرفته'};
const CAP_RISK_FA={LOW:'کم',MEDIUM:'متوسط',HIGH:'بالا'};
const CAP_KIND_FA={PERSON:'فرد',ASSET:'دارایی'};
